import { memo } from 'react';
import Svg, { Circle, Ellipse, Line, Path, Polygon, Polyline, Rect } from 'react-native-svg';
import type { ColorToken } from '@kanon/tokens';
import { ICON_NODES, type IconName, type IconShape } from '../lib/icon-nodes';
import { useTheme } from '../theme';

/**
 * The icon set. One geometry (24 grid), one stroke (1.75), round caps and joins,
 * so every glyph carries the same optical weight next to monospaced type.
 *
 * Shapes come from lucide (ISC licence; the notice sits in `lib/icon-nodes.ts`,
 * which is generated by `packages/ui/scripts/gen-icons.mjs`), drawn through
 * react-native-svg so the same component renders on the phone and, via
 * react-native-web, in the browser.
 *
 * Rules (docs/DESIGN.md, Iconography):
 *  - Colour is a token name, resolved through the theme. Never pass a hex.
 *  - Sizes are 14 (inline with 11-13px text), 16, 18 (rows), 20 (buttons),
 *    22 (tab bar). Do not scale to fit; pick the size.
 *  - Green/red icons (`trending-*`, `arrow-up/down`) are direction only and
 *    always sit next to a label or a signed figure.
 */

/** Every icon name, for lookups and pickers. */
export type Icon = IconName;

export const ICON_NAMES = Object.keys(ICON_NODES) as Icon[];

export const ICON_STROKE = 1.75;

export interface IconProps {
  name: Icon;
  /** Edge length in px. Default 18. */
  size?: number | undefined;
  /** A colour token. Default `bone`. */
  color?: ColorToken | undefined;
  /** Stroke width on the 24 grid. Default 1.75; use 2 only for a filled-look emphasis. */
  strokeWidth?: number | undefined;
  /** Accessible name. Omit for a decorative icon (the common case: a label sits beside it). */
  label?: string | undefined;
}

function shape([tag, attrs]: IconShape, i: number) {
  const p = attrs as Record<string, string | number>;
  switch (tag) {
    case 'path':
      return <Path key={i} d={String(p.d)} />;
    case 'circle':
      return <Circle key={i} cx={Number(p.cx)} cy={Number(p.cy)} r={Number(p.r)} />;
    case 'ellipse':
      return <Ellipse key={i} cx={Number(p.cx)} cy={Number(p.cy)} rx={Number(p.rx)} ry={Number(p.ry)} />;
    case 'line':
      return (
        <Line key={i} x1={Number(p.x1)} y1={Number(p.y1)} x2={Number(p.x2)} y2={Number(p.y2)} />
      );
    case 'polyline':
      return <Polyline key={i} points={String(p.points)} />;
    case 'polygon':
      return <Polygon key={i} points={String(p.points)} />;
    case 'rect':
      return (
        <Rect
          key={i}
          x={Number(p.x ?? 0)}
          y={Number(p.y ?? 0)}
          width={Number(p.width)}
          height={Number(p.height)}
          {...(p.rx !== undefined ? { rx: Number(p.rx) } : null)}
          {...(p.ry !== undefined ? { ry: Number(p.ry) } : null)}
        />
      );
  }
}

function IconBase({
  name,
  size = 18,
  color = 'bone',
  strokeWidth = ICON_STROKE,
  label,
}: IconProps) {
  const { colors } = useTheme();
  const nodes: readonly IconShape[] = ICON_NODES[name];
  return (
    <Svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke={colors[color]}
      strokeWidth={strokeWidth}
      strokeLinecap="round"
      strokeLinejoin="round"
      {...(label
        ? { role: 'img', 'aria-label': label }
        : { 'aria-hidden': true, focusable: false })}
    >
      {nodes.map(shape)}
    </Svg>
  );
}

/**
 * `<Icon name="sparkles" size={20} color="signal" />`
 *
 * Memoised: icons sit in long lists and only re-render on a real prop change.
 */
export const Icon = memo(IconBase);
